frappe.query_reports["Biometric Attendance Log"] = {

    get_datatable_options(options) {
		return Object.assign(options, {
			checkboxColumn: true,
		});
	},

	onload: function(report) {
	    report.page.add_action_item("Reset Log", function() {
			let checked_rows_indexes = report.datatable.rowmanager.getCheckedRows();
			let checked_rows = checked_rows_indexes.map(i => {
			    frappe.call("real_group.real_group.attendance.reset_attendance_log", {
			        "bio_id": report.data[i].name
			    })
			});
		});
    },

    "filters": [
        {
            "fieldname": "from_date",
            "fieldtype": "Date",
            "default": frappe.datetime.month_start(),
            "reqd": 1,
            "label": "From Date"
        },
        {
            "fieldname": "to_date",
            "fieldtype": "Date",
            "default": frappe.datetime.get_today(),
            "reqd": 1,
            "label": "To Date"
        },
        {
            "fieldname": "employee",
            "fieldtype": "Link",
            "options": "Employee",
            "label": "Employee"
        },
        {
            "fieldname": "is_processed",
            "fieldtype": "Select",
            "options": "\nYes\n\No\nError",
            "label": "Is Processed"
        }
    ]
}

report_script:
from_date = filters.get("from_date")
to_date = filters.get("to_date")
employee = filters.get("employee")
is_processed = filters.get("is_processed")

if is_processed:
    if is_processed == "Yes":
        is_processed = "Y"
    if is_processed == "No":
        is_processed = "N"
    if is_processed == "Error":
        is_processed = "E"

columns = [
    {
        "fieldtype": "Data",
        "fieldname": "employee_id",
        "label": "Employee Id"
    },
    {
        "fieldtype": "Date",
        "fieldname": "punch_date",
        "label": "Punch Date"
    },
    {
        "fieldtype": "Data",
        "fieldname": "punch_time",
        "label": "Punch Time"
    },
    {
        "fieldtype": "Data",
        "fieldname": "area",
        "label": "Area"
    },
    {
        "fieldtype": "Data",
        "fieldname": "terminal_id",
        "label": "Machine Id"
    },
    {
        "fieldtype": "Data",
        "fieldname": "punch_direction",
        "label": "Punch Direction"
    },
    {
        "fieldtype": "Data",
        "fieldname": "is_processed",
        "label": "Is Processed"
    },
    {
        "fieldtype": "Data",
        "fieldname": "message",
        "label": "Message"
    }

]

conditions = ""
employee_cond = ""
is_processed_cond = ""

if employee:
    employee_cond = f" AND employee_id = '{employee}'"

if is_processed:
    is_processed_cond = f" AND is_processed = '{is_processed}'"

conditions = f"{conditions} {employee_cond} {is_processed_cond}"

sql = f"""
    SELECT
    name,
    employee_id,
    punch_time,
    punch_date,
    area,
    terminal_id,
    punch_direction,
    is_processed,
    message
FROM
    bio_attendance_log
WHERE
    punch_date between '{from_date}' and '{to_date}' {conditions}
"""

result = frappe.db.sql(sql, as_dict=True)

data = columns, result

